(() => {
  const output = document.getElementById("home-total-pageviews");
  if (!output) return;

  fetch(`/data/site-traffic.json?t=${Date.now()}`, { cache: "no-store" })
    .then((response) => {
      if (!response.ok) throw new Error("traffic unavailable");
      return response.json();
    })
    .then((data) => {
      const total = data.total_pageviews ?? data.pageviews_total ?? data.total;
      output.textContent = Number.isFinite(Number(total)) ? Number(total).toLocaleString("en-US") : "—";
    })
    .catch(() => {
      output.textContent = "—";
    });
})();
</script>

